class Context {
    private Behavior behavior;
    Context(Behavior behavior) { this.behavior = behavior; }
    void handle() { behavior.handle(); }
}

interface Behavior { void handle(); }

class ConcreteA implements Behavior { public void handle() { } }
class ConcreteB implements Behavior { public void handle() { } }

class Checkout {
    void pay(String mode, int amount) {
        switch (mode) {
            case "card" -> chargeCard(amount);
            case "cash" -> takeCash(amount);
        }
    }
}

interface PaymentStrategy { void pay(int amount); }

class CardPayment implements PaymentStrategy {
    public void pay(int amount) { System.out.println("card " + amount); }
}

class CashPayment implements PaymentStrategy {
    public void pay(int amount) { System.out.println("cash " + amount); }
}

// CardPayment prints "card <amount>"; CashPayment prints "cash <amount>".
Checkout checkout = new Checkout(new CardPayment());
checkout.pay(100);
checkout.pay(50);

class CardPayment implements PaymentStrategy {
    public void pay(Checkout checkout, int amount) {
        System.out.println("card " + amount);
        checkout.setStrategy(new CashPayment());
    }
}

interface OrderState {
    void pay(Order order);
    void ship(Order order);
}

class PlacedState implements OrderState { /* ... */ }
class PaidState implements OrderState { /* ... */ }
class ShippedState implements OrderState { /* ... */ }

class PlacedState implements OrderState {
    public void pay(Order order) {
        System.out.println("paid");
    }
}

// Order delegates every call to its current OrderState.
// PlacedState.pay(order) charges through the injected PaymentStrategy,
// then calls order.setState(new PaidState()).
// PaidState.pay(order) rejects the call.
Order order = new Order(new CardPayment());   // state = PlacedState
order.pay();
order.pay();
System.out.println(order.state() + " / " + order.strategy());

